#!/usr/bin/env node
/**
 * Build the hosted AAJ Engines MCP server (roadmap R6, Oct 10, 2026).
 *
 * Cloudflare Workers can't spawn Node or eval code, so every engine is compiled
 * into a plain function at build time: its unchanged source, wrapped so that
 * `console`, `process`, `require("fs")` and `module` are small stand-ins that
 * capture output and exit codes. The wrapped source is byte-for-byte the
 * engine file between the wrapper lines, and a check (--check) fails if the
 * generated file is stale.
 *
 *   node platform/mcp-worker/build.mjs          # write platform/mcp-worker/engines.generated.mjs
 *   node platform/mcp-worker/build.mjs --check  # exit 1 if it would change
 *
 * The bundle carries a build stamp (BUILD: version, git short SHA, build time,
 * engine count and engine hash) that the Worker serves at /version, in /health
 * and in its MCP initialize response. --check ignores the stamp line.
 */
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { execFileSync } from "node:child_process";
import { join, dirname, resolve, basename } from "node:path";
import { fileURLToPath } from "node:url";
import { listSkills, engineHelp } from "../lib/catalog.mjs";
import { engineSummary, SERVER_NAME, SERVER_VERSION } from "../mcp/core.mjs";
import { engineFingerprint, readGitHead } from "../lib/stamp.mjs";
import { buildCounts } from "../lib/counts.mjs";
import { buildSpec, specForAgent, loadEnvironments } from "../lib/specs.mjs";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(HERE, "..", "..");
const OUT = join(HERE, "engines.generated.mjs");
const SKILLS_SITE = "https://skills.aajconsult.com";

const skills = listSkills(ROOT);
const env = loadEnvironments(ROOT);
const skillRows = [];
const engineRows = [];
const fns = [];

for (const s of skills) {
  skillRows.push({
    slug: s.slug, name: s.name, title: s.title, description: s.description,
    category: s.category, body: s.body, hasEngine: s.hasEngine, url: `${SKILLS_SITE}/skills/${s.slug}`,
  });
  for (const f of s.jsFiles) {
    const file = join(s.resourcesDir, f);
    const id = s.jsFiles.length === 1 ? s.slug : `${s.slug}:${basename(f, ".js")}`;
    const help = engineHelp(file);
    const original = readFileSync(file, "utf8");
    let src = original.replace(/\r\n/g, "\n");
    if (src.startsWith("#!")) src = src.slice(src.indexOf("\n") + 1);
    if (/^\s*(import|export)\s/m.test(src.replace(/\/\*[\s\S]*?\*\//g, "").replace(/(^|[^:])\/\/.*$/gm, ""))) {
      throw new Error(`${id}: ES module syntax is not supported in an engine (engines are CommonJS scripts)`);
    }
    // What the engine reads back from its own file for --help: the original text up to the header's end.
    const end = original.indexOf("*/");
    const head = end >= 0 ? original.slice(0, end + 2) : "";
    engineRows.push({ id, slug: s.slug, help, summary: engineSummary(help, s.description), skillName: s.title, category: s.category, file: `skills/${s.slug}/resources/${f}`, head, specText: specForAgent(buildSpec(s, file, id, env)) });
    fns.push(`  ${JSON.stringify(id)}: function (console, process, require, module, exports, __filename, __dirname) {\n// ---- begin ${s.slug}/resources/${f} ----\n${src}\n// ---- end ${s.slug}/resources/${f} ----\n  }`);
  }
}

// Which commit this bundle was built from. "-dirty" marks a build from a working
// tree with uncommitted changes to tracked files (a deploy from a local copy).
function commitOf(root) {
  const git = (...a) => execFileSync("git", ["-C", root, ...a], { encoding: "utf8", stdio: ["ignore", "pipe", "ignore"], timeout: 5000 }).trim();
  try {
    const sha = git("rev-parse", "--short=7", "HEAD");
    return git("status", "--porcelain", "--untracked-files=no") ? `${sha}-dirty` : sha;
  } catch {
    return (process.env.GITHUB_SHA || "").slice(0, 7) || readGitHead(root) || "unknown";
  }
}
const BUILD = {
  server: SERVER_NAME,
  version: SERVER_VERSION,
  commit: commitOf(ROOT),
  builtAt: new Date().toISOString().replace(/\.\d{3}Z$/, "Z"),
  skills: skillRows.length,
  ...engineFingerprint(skills),
  runtime: "hosted",
};

const out = `/* AUTO-GENERATED by platform/mcp-worker/build.mjs from skills/ — do not edit.
   ${skillRows.length} skills, ${engineRows.length} engines. */
export const BUILD = ${JSON.stringify(BUILD)};
export const SKILLS = ${JSON.stringify(skillRows)};
export const COUNTS = ${JSON.stringify(buildCounts(skills))};
export const ENGINES = ${JSON.stringify(engineRows)};
export const RUNNERS = {
${fns.join(",\n")}
};
`;

if (process.argv.includes("--check")) {
  const unstamped = (s) => s.replace(/^export const BUILD = .*$/m, "");
  const cur = existsSync(OUT) ? readFileSync(OUT, "utf8") : "";
  if (unstamped(cur) !== unstamped(out)) { console.error("engines.generated.mjs is stale. Run: node platform/mcp-worker/build.mjs"); process.exit(1); }
  console.log(`engines.generated.mjs up to date — ${skillRows.length} skills, ${engineRows.length} engines`);
} else {
  writeFileSync(OUT, out);
  console.log(`wrote engines.generated.mjs — ${skillRows.length} skills, ${engineRows.length} engines, ${(out.length / 1024).toFixed(0)} KB, commit ${BUILD.commit}, engine hash ${BUILD.engineHash}`);
}
